 if(!state.settings.global.sync)state.settings.global.sync={mode:'local-first',status:'ready',provider:'shared-database',transport:'pending',deviceId:null,lastAttemptAt:null,lastSuccessAt:null,lastReceivedAt:null,queue:0,revision:0};
