 const deliveryIcon=L.divIcon({className:'rm-map-icon-wrap',html:'<div class="rm-map-icon delivery" aria-label="Entrega">📍</div>',iconSize:[38,38],iconAnchor:[19,19],popupAnchor:[0,-18]});
 const clusterIcon=(count,type)=>L.divIcon({className:'rm-map-cluster-wrap',html:`<div class="rm-map-cluster ${type}"><strong>${count}</strong><small>${type==='delivery'?'entregas':'motoboys'}</small></div>`,iconSize:[54,54],iconAnchor:[27,27]});
