 const restaurantCoords=Array.isArray(state.settings.map?.restaurantCoords)&&state.settings.map.restaurantCoords.length>=2?[Number(state.settings.map.restaurantCoords[0]),Number(state.settings.map.restaurantCoords[1])]:null;
 if(restaurantCoords){data.restaurant=restaurantCoords;data.allPoints.push(restaurantCoords);L.marker(restaurantCoords,{icon:restaurantIcon}).addTo(staticLayer).bindPopup(`<b>🏪 ${esc(state.settings.restaurant||'Restaurante')}</b><br><span class="muted">Ponto configurado pelo endereço</span>`)}else{const note=L.control({position:'topright'});note.onAdd=()=>{const d=L.DomUtil.create('div','map-empty-note map-empty-top');d.innerHTML='<b>Endereço do restaurante não localizado</b><span>Configure o endereço em Configurações → Geral.</span>';return d};note.addTo(map)}
 let locatedBikes=0,locatedDeliveries=0;
