 for(const o of active){const coords=orderCoords(o);if(coords){locatedDeliveries++;data.deliveries.push({coords,customer:o.customer,address:o.address,id:o.id,num:o.num,status:o.status});data.allPoints.push(coords)}else if(o.address)pending.deliveries.push(o)}
 const buildClusters=(items,type)=>{const threshold=Math.max(30,Math.min(62,72-(map.getZoom()-10)*7));const buckets=[];for(const point of items){const p=map.latLngToLayerPoint(point.coords);let bucket=null;for(const g of buckets){if(p.distanceTo(g.center)<=threshold){bucket=g;break}}if(!bucket){bucket={center:p,items:[]};buckets.push(bucket)}bucket.items.push(point);const avg=bucket.items.reduce((a,x)=>[a[0]+x.coords[0],a[1]+x.coords[1]],[0,0]).map(v=>v/bucket.items.length);bucket.center=map.latLngToLayerPoint(avg)}return buckets};
 const renderType=(items,type,layer)=>{layer.clearLayers();if(window.__rotaMapMode!=='all'&&window.__rotaMapMode!==type)return;for(const g of buildClusters(items,type)){const first=g.items[0];if(g.items.length===1){const marker=L.marker(first.coords,{icon:type==='delivery'?deliveryIcon:bikeIcon});if(type==='delivery')marker.bindPopup(`<b>📍 ${esc(first.customer)}</b><br>${esc(first.address)}<br><span class="muted">Pedido #${esc(first.num||'—')}</span><br><button class="btn small" data-map-detail="${first.id}">Abrir entrega</button>`);else marker.bindPopup(`<b>🛵 ${esc(first.name)}</b><br><span>${esc(first.status)}</span>${first.query?`<br>${esc(first.query)}`:''}`);marker.addTo(layer)}else{const center=map.layerPointToLatLng(g.center);const marker=L.marker(center,{icon:clusterIcon(g.items.length,type)});marker.on('click',()=>map.setView(center,Math.min(18,map.getZoom()+2),{animate:true}));marker.bindTooltip(`${g.items.length} ${type==='delivery'?'entregas':'motoboys'}`,{direction:'top',offset:[0,-20]});marker.addTo(layer)}}};
