 document.querySelectorAll('[data-map-mode]').forEach(b=>b.onclick=()=>window.__rotaMapSetMode(b.dataset.mapMode));document.querySelector('[data-map-overview]')?.addEventListener('click',fitOverview);
 document.querySelector('[data-map-fullscreen]')?.addEventListener('click',async()=>{const target=document.querySelector('.map-ready');try{if(!document.fullscreenElement&&target?.requestFullscreen)await target.requestFullscreen();else if(document.fullscreenElement)await document.exitFullscreen();else target?.classList.toggle('map-fullscreen-fallback')}catch(_){target?.classList.toggle('map-fullscreen-fallback')}setTimeout(()=>map.invalidateSize(),180)});
 map.on('zoomend moveend',renderLayers);map.on('popupopen',e=>e.popup.getElement()?.querySelector('[data-map-detail]')?.addEventListener('click',ev=>openDetail(ev.currentTarget.dataset.mapDetail)));document.addEventListener('fullscreenchange',()=>setTimeout(()=>map.invalidateSize(),120));
 if(!active.length){const note=L.control({position:'bottomleft'});note.onAdd=()=>{const d=L.DomUtil.create('div','map-empty-note');d.innerHTML='<b>Nenhuma entrega ativa</b><span>O mapa continua mostrando o restaurante e os motoboys.</span>';return d};note.addTo(map)}
 if(!state.bikes.length){const note=L.control({position:'topright'});note.onAdd=()=>{const d=L.DomUtil.create('div','map-empty-note map-empty-top');d.innerHTML='<b>Nenhum motoboy cadastrado</b><span>Cadastre um motoboy para acompanhar a equipe no mapa.</span>';return d};note.addTo(map)}
 fitOverview();setTimeout(()=>map.invalidateSize(),120);
 // Geocode missing locations after the first usable map render, preserving responsiveness with large datasets.
