 const choices=candidates.map(order=>{const delivery=state.deliveries.find(row=>row.id===order.deliveryId||row.orderId===order.id);const id=delivery?.id||order.deliveryId;if(!id)return '';const owner=ownerFor(id);const checked=currentIds.has(id);const terminal=['FINALIZADA','CANCELADA'].includes(order.status);const locked=terminal&&checked;const position=(current?.deliveryIds||[]).findIndex(value=>routeDeliveryLocalId(value)===id)+1||active.indexOf(order)+1;return `<label class="assignment-row ${owner&&!checked||locked?'disabled':''}"><input type="checkbox" data-route-delivery="${esc(id)}" ${checked?'checked':''} ${owner&&!checked||locked?'disabled':''}><span><b>#${esc(order.num||order.number||'—')} · ${esc(order.customer||'Cliente')}</b><small>${esc(order.address||'Endereço não informado')} · ${esc(order.bike||'Sem motorista atribuído')} ${locked?' · parada histórica preservada':owner&&!checked?' · já planejada em outra rota':''}</small></span><span>${statusLabel(order.status)}</span><input class="input route-stop-position" type="number" min="1" max="500" value="${position}" data-route-position aria-label="Posição da parada para pedido ${esc(order.num||order.number||'')}" ${checked&&!locked?'':'disabled'}></label>`}).join('');
