async function refreshIFoodStatus(showToast=false){if(!window.RotaMotoIFood?.status)return;try{const base=String(state.settings.ifood?.backendUrl||'/api/ifood').replace(/\/$/,'');const r=await fetch(base+'/status',{headers:{Accept:'application/json'},cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.message||'Serviço iFood indisponível.');state.settings.ifood={...state.settings.ifood,status:data.status||'not_configured',merchantId:state.settings.ifood.merchantId||null,lastPollAt:data.lastPollAt||null,lastSuccessAt:data.lastSuccessAt||null,lastError:data.lastError||null,pendingEvents:Number(data.pendingEvents||0)};await setMeta('settings',state.settings);if(showToast)toast('Conexão com o serviço iFood verificada.','success');render()}catch(e){state.settings.ifood.lastError={message:e.message,at:Date.now()};await setMeta('settings',state.settings);if(showToast)toast(e.message||'Não foi possível consultar o serviço iFood.','error');render()}}
